  $tok=function($s){ $s=mb_strtolower($s); $s=str_replace(array(',',';','(',')','/','+','&','-','–','’',"'"),' ',$s); $s=preg_replace('/(\d)\s*(kg|g|l|ml|m|cm|vnt|x)\b/u','$1$2',$s); $t=preg_split('/\s+/u',$s); return array_values(array_unique(array_filter($t,function($x){return mb_strlen($x)>=2 && !in_array($x,array('su','ir','kg','sausas','maistas','pašaras','šunims','katėms','šunų','kačių','skanėstas','skanėstai','šlapias','konservai'));}))); };
  try{
    $out=array();
    foreach($rows as $r){
      $cand=$wpdb->get_results($wpdb->prepare("SELECT po.ID, po.post_title FROM {$p}posts po JOIN {$p}postmeta pm ON pm.post_id=po.ID AND pm.meta_key='_price' WHERE po.post_type='product' AND po.post_status='publish' AND ABS(CAST(pm.meta_value AS DECIMAL(10,2))-%f)<0.006",$r['m']),ARRAY_A);
      $best=null; $bs=-1; $a=$tok($r['n']);
      foreach($cand as $c){ $b=$tok($c['post_title']); $inter=count(array_intersect($a,$b)); $sc=$inter/max(1,min(count($a),count($b))); if($sc>$bs){$bs=$sc;$best=$c;} }
      $row=array('i'=>$r['i'],'kainos'=>$r['n'],'b'=>$r['b'],'musu'=>$r['m'],'min'=>$r['k'],'diff'=>$r['d'],'kas'=>$r['s'],'kand'=>count($cand));
      if($best){ $id=(int)$best['ID']; $sav=0; $sk='';
        foreach(array('_cost_price','_vf_cost','_zb_cost') as $k){ $v=(float)str_replace(',','.',(string)get_post_meta($id,$k,true)); if($v>0){$sav=$v;$sk=$k;break;} }
        $row+=array('pid'=>$id,'wc'=>$best['post_title'],'score'=>round($bs,2),'sav'=>$sav,'sav_k'=>$sk,'sand'=>get_post_meta($id,'_ps_sandelis',true),'stock'=>get_post_meta($id,'_stock',true),'reg'=>get_post_meta($id,'_regular_price',true),'sale'=>get_post_meta($id,'_sale_price',true));
      }
      $out[]=$row;
    }
    $o['rows']=$out;
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
